import { expect, test } from "../../fixtures";

test("current user is returned for a valid session", { tag: "@AUTH-04" }, async ({ apiAs }) => {
  const member = await apiAs("member");

  const response = await member.get("/api/me");
  const body = await response.text();
  expect(response.status(), body).toBe(200);

  const profile = JSON.parse(body) as { role: string; tenant: { name: string } };
  expect(profile.role, body).toBe("member");
  expect(profile.tenant.name, body).toBe("Northwind Supply");
});
